//! Instanced architectural modules: openings with their mouldings,
//! joinery, glazing, shutters and balconies, ground-floor shops and
//! portals, balustrades, dormers and rooftop clutter.
//!
//! Module frame: origin at the bottom centre of the opening on the facade
//! plane, +X along the facade (right when facing it), +Y up, +Z out of the
//! wall. The wall itself (with the recessed reveal) is generated by the
//! facade builder; modules sit in and in front of the hole.

use forja_math::{Mat4, Quat, Vec2, Vec3};

use crate::geom::{Parts, Prim, Rng};
use crate::kit::{Mat, Rgb, hex};
use crate::style::ShutterKind;

/// Depth of the wall reveal around every opening.
pub const REVEAL: f32 = 0.30;
/// Frame plane inside the reveal.
const FRAME_Z: f32 = -0.22;

pub type P = Parts<Mat>;

fn bx(p: &mut P, m: Mat, min: Vec3, max: Vec3) {
    let s = m.scale();
    p.get(m).aabox(min, max, s);
}

fn v(x: f32, y: f32, z: f32) -> Vec3 {
    Vec3::new(x, y, z)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum SurroundKind {
    None,
    Plain,
    Lintel,
    Keystone,
    Pediment,
    Eared,
}

impl SurroundKind {
    pub fn parse(s: &str) -> Self {
        match s {
            "none" => SurroundKind::None,
            "lintel" => SurroundKind::Lintel,
            "keystone" => SurroundKind::Keystone,
            "pediment" => SurroundKind::Pediment,
            "eared" => SurroundKind::Eared,
            _ => SurroundKind::Plain,
        }
    }
}

/// Moulded frame around an opening `w × h` starting at `bottom`.
pub fn surround(p: &mut P, m: Mat, kind: SurroundKind, w: f32, h: f32, bottom: f32, sill: bool) {
    if kind == SurroundKind::None {
        return;
    }
    let (bw, pr) = (0.15, 0.045);
    let hw = w * 0.5;
    bx(p, m, v(-hw - bw, bottom, 0.0), v(-hw, h, pr));
    bx(p, m, v(hw, bottom, 0.0), v(hw + bw, h, pr));
    bx(p, m, v(-hw - bw, h, 0.0), v(hw + bw, h + bw, pr));
    if sill {
        bx(p, m, v(-hw - bw - 0.06, bottom - 0.1, 0.0), v(hw + bw + 0.06, bottom, pr + 0.08));
    }
    let top = h + bw;
    match kind {
        SurroundKind::Lintel | SurroundKind::Pediment => {
            bx(p, m, v(-hw - bw - 0.1, top, 0.0), v(hw + bw + 0.1, top + 0.07, pr + 0.1));
            bx(p, m, v(-hw - bw - 0.15, top + 0.07, 0.0), v(hw + bw + 0.15, top + 0.13, pr + 0.15));
            // Consoles under the cornice.
            for x in [-hw - bw * 0.5, hw + bw * 0.5] {
                bx(p, m, v(x - 0.055, h - 0.32, pr), v(x + 0.055, top, pr + 0.07));
                bx(p, m, v(x - 0.045, h - 0.4, pr), v(x + 0.045, h - 0.32, pr + 0.035));
            }
            if kind == SurroundKind::Pediment {
                let (y0, half, rise) = (top + 0.13, hw + bw + 0.15, 0.5);
                let s = m.scale();
                let prim = p.get(m);
                let apex = v(0.0, y0 + rise, pr + 0.1);
                prim.tri(v(-half + 0.1, y0, pr + 0.1), v(half - 0.1, y0, pr + 0.1), apex, [Vec2::ZERO, Vec2::new(1.0, 0.0), Vec2::new(0.5, 0.5)]);
                prim.beam(v(-half, y0, pr + 0.08), v(0.0, y0 + rise + 0.06, pr + 0.08), Vec3::Z, 0.16, 0.12, s);
                prim.beam(v(half, y0, pr + 0.08), v(0.0, y0 + rise + 0.06, pr + 0.08), Vec3::Z, 0.16, 0.12, s);
            }
        }
        SurroundKind::Keystone => {
            bx(p, m, v(-hw - bw - 0.08, top, 0.0), v(hw + bw + 0.08, top + 0.06, pr + 0.06));
            let prim = p.get(m);
            // Tapered keystone.
            let k = [Vec2::new(-0.09, h - 0.08), Vec2::new(0.09, h - 0.08), Vec2::new(0.14, top + 0.16), Vec2::new(-0.14, top + 0.16)];
            prim.extrude_xy(&k, 0.0, pr + 0.07, 1.0, |q| q);
        }
        SurroundKind::Eared => {
            for (x0, x1) in [(-hw - bw - 0.1, -hw - bw), (hw + bw, hw + bw + 0.1)] {
                bx(p, m, v(x0, h - 0.14, 0.0), v(x1, top, pr));
            }
            bx(p, m, v(-hw - bw - 0.12, top, 0.0), v(hw + bw + 0.12, top + 0.05, pr + 0.04));
        }
        _ => {}
    }
}

/// Window joinery and glass in the reveal.
fn glazing(p: &mut P, frame: Mat, w: f32, h: f32, door: bool) {
    let (fw, z) = (0.065, FRAME_Z);
    let hw = w * 0.5;
    bx(p, frame, v(-hw, 0.0, z - 0.03), v(-hw + fw, h, z + 0.03));
    bx(p, frame, v(hw - fw, 0.0, z - 0.03), v(hw, h, z + 0.03));
    bx(p, frame, v(-hw, h - fw, z - 0.03), v(hw, h, z + 0.03));
    bx(p, frame, v(-hw, 0.0, z - 0.03), v(hw, if door { 0.12 } else { fw }, z + 0.03));
    let transom = if h > 1.9 { h - 0.48 } else { h };
    if transom < h {
        bx(p, frame, v(-hw, transom - 0.03, z - 0.03), v(hw, transom + 0.03, z + 0.03));
    }
    // Two leaves.
    bx(p, frame, v(-0.035, 0.0, z - 0.025), v(0.035, transom, z + 0.035));
    for (x0, x1) in [(-hw + fw, -0.035), (0.035, hw - fw)] {
        // Glazing bar and lower panel on balcony doors.
        let mid = if door { 0.55 + (transom - 0.55) * 0.5 } else { transom * 0.5 };
        bx(p, frame, v(x0, mid - 0.015, z - 0.015), v(x1, mid + 0.015, z + 0.02));
        if door {
            bx(p, frame, v(x0, 0.12, z - 0.02), v(x1, 0.55, z + 0.02));
            bx(p, frame, v(x0 + 0.06, 0.18, z + 0.02), v(x1 - 0.06, 0.49, z + 0.035));
        }
    }
    let g = p.get(Mat::Glass);
    let zg = z - 0.005;
    let y0 = if door { 0.55 } else { fw };
    g.quad_uv([v(-hw, y0, zg), v(hw, y0, zg), v(hw, h, zg), v(-hw, h, zg)], [Vec2::new(0.0, 1.0), Vec2::new(1.0, 1.0), Vec2::new(1.0, 0.0), Vec2::ZERO]);
}

/// Fake room behind the glass (atlas column `k` of the interior texture).
fn interior(p: &mut P, m: Mat, w: f32, h: f32, k: u8, depth: f32) {
    let (x0, x1) = (-w * 0.5 - 0.6, w * 0.5 + 0.6);
    let (y0, y1) = (-0.3, h + 0.5);
    let (zf, zb) = (-REVEAL, -REVEAL - depth);
    let u0 = k as f32 * 0.25;
    let u = |t: f32| u0 + 0.02 + t * 0.21;
    let prim = p.get(m);
    prim.quad_uv([v(x0, y0, zb), v(x1, y0, zb), v(x1, y1, zb), v(x0, y1, zb)], [Vec2::new(u(0.0), 1.0), Vec2::new(u(1.0), 1.0), Vec2::new(u(1.0), 0.05), Vec2::new(u(0.0), 0.05)]);
    prim.quad_uv([v(x0, y1, zb), v(x1, y1, zb), v(x1, y1, zf), v(x0, y1, zf)], [Vec2::new(u(0.0), 0.05), Vec2::new(u(1.0), 0.05), Vec2::new(u(1.0), 0.0), Vec2::new(u(0.0), 0.0)]);
    prim.quad_uv([v(x0, y0, zf), v(x1, y0, zf), v(x1, y0, zb), v(x0, y0, zb)], [Vec2::new(u(0.0), 1.0), Vec2::new(u(1.0), 1.0), Vec2::new(u(1.0), 0.95), Vec2::new(u(0.0), 0.95)]);
    prim.quad_uv([v(x0, y0, zf), v(x0, y0, zb), v(x0, y1, zb), v(x0, y1, zf)], [Vec2::new(u(0.0), 1.0), Vec2::new(u(0.1), 1.0), Vec2::new(u(0.1), 0.05), Vec2::new(u(0.0), 0.05)]);
    prim.quad_uv([v(x1, y0, zb), v(x1, y0, zf), v(x1, y1, zf), v(x1, y1, zb)], [Vec2::new(u(0.9), 1.0), Vec2::new(u(1.0), 1.0), Vec2::new(u(1.0), 0.05), Vec2::new(u(0.9), 0.05)]);
}

/// Rolled Valencian slat blind hanging from the lintel; drapes over the
/// balcony railing when lowered past it.
fn alicantina(p: &mut P, m: Mat, w: f32, h: f32, lowered: f32, balcony: Option<f32>) {
    let half = w * 0.5 + 0.06;
    let mut path: Vec<Vec2> = vec![Vec2::new(0.1, h + 0.05)]; // (z, y)
    let want = lowered * (h + 0.05);
    match balcony {
        Some(d) if h + 0.05 - want < 1.05 => {
            path.push(Vec2::new(d + 0.05, 1.05));
            path.push(Vec2::new(d + 0.1, 0.25));
        }
        _ => path.push(Vec2::new(0.16, -0.05)),
    }
    let s = m.scale();
    let prim = p.get(m);
    let (pitch, mut walked) = (0.048, 0.0);
    let mut last = path[0];
    'outer: for seg in path.windows(2) {
        let (a, b) = (seg[0], seg[1]);
        let len = (b - a).length();
        let dir = (b - a) / len;
        let mut t = 0.0;
        while t < len {
            if walked >= want {
                break 'outer;
            }
            let q = a + dir * t;
            last = q;
            let side = Vec3::new(0.0, dir.y, dir.x);
            prim.beam(v(-half, q.y, q.x), v(half, q.y, q.x), side, 0.04, 0.012, s);
            t += pitch;
            walked += pitch;
        }
    }
    if lowered < 0.97 {
        prim.cylinder(v(-half, last.y - 0.05, last.x + 0.02), v(half, last.y - 0.05, last.x + 0.02), 0.055, 10, true);
    }
    // Cords.
    let cord = Mat::Plastic(hex(0xd8d0bc));
    let c = p.get(cord);
    for x in [-half + 0.12, half - 0.12] {
        c.beam(v(x, h + 0.08, 0.11), v(x, last.y, last.x + 0.015), Vec3::X, 0.008, 0.008, 1.0);
    }
}

/// One louvred leaf of width `w`, hinge at local x = 0, extending +X.
fn louvre_leaf(m: Mat, w: f32, h: f32) -> P {
    let mut p = P::new();
    let (st, t) = (0.055, 0.035);
    bx(&mut p, m, v(0.0, 0.0, -t), v(st, h, 0.0));
    bx(&mut p, m, v(w - st, 0.0, -t), v(w, h, 0.0));
    bx(&mut p, m, v(st, 0.0, -t), v(w - st, 0.1, 0.0));
    bx(&mut p, m, v(st, h - 0.08, -t), v(w - st, h, 0.0));
    bx(&mut p, m, v(st, h * 0.45, -t), v(w - st, h * 0.45 + 0.07, 0.0));
    let s = m.scale();
    let prim = p.get(m);
    let mut y = 0.14;
    while y < h - 0.1 {
        if (y - h * 0.45).abs() > 0.06 {
            // Slats tilted 40 degrees, shedding rain outwards.
            let side = Vec3::new(0.0, 0.64, 0.77);
            prim.beam(v(st, y, -t * 0.5), v(w - st, y, -t * 0.5), side, 0.05, 0.008, s);
        }
        y += 0.055;
    }
    p
}

fn louvres(p: &mut P, m: Mat, w: f32, h: f32, state: u8) {
    let lw = w * 0.5;
    let z = -0.12;
    // Angles of the left/right leaves: 0 = closed, 90 = open outwards.
    let (al, ar) = match state % 4 {
        0 => (0.0f32, 0.0f32),
        1 => (90.0, 90.0),
        2 => (0.0, 95.0),
        _ => (35.0, 60.0),
    };
    let leaf = louvre_leaf(m, lw, h);
    // Rotating +X by -angle about Y swings the leaf out of the wall (+Z).
    let left = Mat4::from_translation(v(-w * 0.5, 0.0, z)) * Mat4::from_rotation_y((-al).to_radians());
    let right = Mat4::from_translation(v(w * 0.5, 0.0, z)) * Mat4::from_rotation_y((180.0 + ar).to_radians()) * Mat4::from_scale(v(1.0, 1.0, -1.0));
    p.append(&leaf, &left);
    p.append(&leaf, &right);
}

fn roller(p: &mut P, w: f32, h: f32, lowered: f32) {
    let m = Mat::MetalShutter(0);
    let hw = w * 0.5;
    let yb = h - lowered * h;
    let prim = p.get(m);
    prim.quad_uv([v(-hw, yb, -0.08), v(hw, yb, -0.08), v(hw, h, -0.08), v(-hw, h, -0.08)], [Vec2::new(0.0, h - yb), Vec2::new(w, h - yb), Vec2::new(w, 0.0), Vec2::ZERO]);
    bx(p, Mat::Plastic(hex(0xd9d4c8)), v(-hw, yb - 0.04, -0.1), v(hw, yb, -0.06));
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct BalconyKey {
    pub width_cm: u16,
    pub depth_cm: u16,
    pub belly: bool,
    pub ends: (bool, bool),
    pub pots: u8,
    pub awning: Option<u8>,
    /// Cantilevered concrete terrace of a 1960s-80s block instead of a
    /// stone slab on corbels with a wrought-iron railing: 0 = none,
    /// 1 = white render parapet, 2 = brick parapet, 3 = low parapet with a
    /// tube railing, 4 = steel bar railing.
    pub terrace: u8,
}

/// Stone slab on corbels with a wrought-iron railing.
fn balcony(p: &mut P, slab: Mat, b: &BalconyKey, h_window: f32) {
    let w = b.width_cm as f32 / 100.0;
    let d = b.depth_cm as f32 / 100.0;
    let hw = w * 0.5;
    if b.terrace > 0 {
        terrace(p, slab, b, h_window);
        return;
    }
    if b.depth_cm <= FLUSH_CM {
        flush_railing(p, slab, b);
        return;
    }
    bx(p, slab, v(-hw, -0.12, 0.0), v(hw, 0.0, d));
    bx(p, slab, v(-hw - 0.025, -0.17, 0.0), v(hw + 0.025, -0.1, d + 0.03));
    // Corbels.
    for x in [-hw + 0.28, hw - 0.28] {
        bx(p, slab, v(x - 0.06, -0.55, 0.0), v(x + 0.06, -0.17, 0.12));
        bx(p, slab, v(x - 0.055, -0.36, 0.12), v(x + 0.055, -0.17, d * 0.55));
    }
    let iron = Mat::Iron;
    let zf = d - 0.03;
    let rail = |p: &mut P, y: f32, t: f32, z: f32| {
        bx(p, iron, v(-hw + 0.02, y, z - 0.02), v(hw - 0.02, y + t, z + 0.02));
    };
    rail(p, 0.96, 0.045, zf);
    rail(p, 0.05, 0.03, zf);
    rail(p, 0.84, 0.02, if b.belly { zf + 0.04 } else { zf });
    if b.belly {
        rail(p, 0.32, 0.02, zf + 0.11);
        rail(p, 0.62, 0.02, zf + 0.11);
    }
    for (on, x) in [(b.ends.0, -hw + 0.04), (b.ends.1, hw - 0.04)] {
        if !on {
            continue;
        }
        bx(p, iron, v(x - 0.02, 0.96, 0.0), v(x + 0.02, 1.005, zf));
        bx(p, iron, v(x - 0.015, 0.05, 0.0), v(x + 0.015, 0.08, zf));
        let mut z = 0.1;
        while z < zf - 0.05 {
            bx(p, iron, v(x - 0.008, 0.08, z - 0.008), v(x + 0.008, 0.96, z + 0.008));
            z += 0.11;
        }
    }
    let prim = p.get(iron);
    let n = ((w - 0.08) / 0.11).floor().max(1.0) as i32;
    for i in 0..=n {
        let x = -hw + 0.04 + (w - 0.08) * i as f32 / n as f32;
        if b.belly {
            let pts = [v(x, 0.08, zf), v(x, 0.3, zf + 0.11), v(x, 0.64, zf + 0.11), v(x, 0.96, zf)];
            for s in pts.windows(2) {
                prim.beam(s[0], s[1], Vec3::X, 0.016, 0.016, 1.0);
            }
        } else {
            prim.beam(v(x, 0.08, zf), v(x, 0.96, zf), Vec3::X, 0.016, 0.016, 1.0);
        }
    }
    // Decorative scrolls in the top band: small diamonds between bars.
    for i in 0..n {
        let x = -hw + 0.04 + (w - 0.08) * (i as f32 + 0.5) / n as f32;
        let zc = if b.belly { zf + 0.04 } else { zf };
        let c = v(x, 0.9, zc);
        let r = 0.04;
        let pts = [c + v(0.0, r, 0.0), c + v(r, 0.0, 0.0), c + v(0.0, -r, 0.0), c + v(-r, 0.0, 0.0), c + v(0.0, r, 0.0)];
        for s in pts.windows(2) {
            prim.beam(s[0], s[1], Vec3::Z, 0.01, 0.01, 1.0);
        }
    }
    if let Some(a) = b.awning {
        awning(p, a, w + 0.1, h_window + 0.3, d + 0.45, h_window - 0.6);
    }
}

/// Balcony depth (cm) at or under which a balcony is a flush railing.
pub const FLUSH_CM: u16 = 15;

/// Balcón enrasado: on a street too narrow for a balcony, the door gets a
/// thin stone sill and an iron railing just proud of the wall, no slab on
/// corbels.
fn flush_railing(p: &mut P, slab: Mat, b: &BalconyKey) {
    let w = b.width_cm as f32 / 100.0 - 0.5;
    let d = b.depth_cm as f32 / 100.0;
    let hw = w * 0.5;
    bx(p, slab, v(-hw - 0.05, -0.08, 0.0), v(hw + 0.05, 0.0, d));
    let iron = Mat::Iron;
    let zf = d - 0.03;
    bx(p, iron, v(-hw, 0.96, zf - 0.02), v(hw, 1.0, zf + 0.02));
    bx(p, iron, v(-hw, 0.05, zf - 0.015), v(hw, 0.08, zf + 0.015));
    bx(p, iron, v(-hw, 0.84, zf - 0.01), v(hw, 0.86, zf + 0.01));
    for x in [-hw, hw - 0.03] {
        bx(p, iron, v(x, 0.0, 0.0), v(x + 0.03, 1.0, zf + 0.02));
    }
    let prim = p.get(iron);
    let n = ((w - 0.06) / 0.11).floor().max(1.0) as i32;
    for i in 1..n {
        let x = -hw + 0.03 + (w - 0.06) * i as f32 / n as f32;
        prim.beam(v(x, 0.08, zf), v(x, 0.96, zf), Vec3::X, 0.016, 0.016, 1.0);
    }
}

/// Concrete terrace of a 1960s-80s block: a thin cantilevered slab with,
/// by `b.terrace`, a solid parapet in white render or brick capped by a
/// steel tube, a low parapet under a tube railing, or a steel bar railing.
fn terrace(p: &mut P, slab: Mat, b: &BalconyKey, h_window: f32) {
    let w = b.width_cm as f32 / 100.0;
    let d = b.depth_cm as f32 / 100.0;
    let hw = w * 0.5;
    let t = 0.08;
    bx(p, slab, v(-hw, -0.16, 0.0), v(hw, 0.0, d));
    // Drip edge under the slab front.
    bx(p, slab, v(-hw - 0.01, -0.2, d - 0.04), v(hw + 0.01, -0.16, d + 0.01));
    let (pm, ph) = match b.terrace {
        1 => (Mat::Stucco(hex(0xf3f0e9)), 0.95),
        2 => (Mat::Brick(hex(0xffffff)), 0.95),
        3 => (Mat::Stucco(hex(0xf3f0e9)), 0.45),
        _ => (slab, 0.0),
    };
    if ph > 0.0 {
        bx(p, pm, v(-hw, 0.0, d - t), v(hw, ph, d));
        bx(p, slab, v(-hw - 0.01, ph, d - t - 0.01), v(hw + 0.01, ph + 0.04, d + 0.01));
        for (on, x0, x1) in [(b.ends.0, -hw, -hw + t), (b.ends.1, hw - t, hw)] {
            if on {
                bx(p, pm, v(x0, 0.0, 0.0), v(x1, ph, d - t));
            }
        }
    }
    let g = p.get(Mat::Galvanized);
    let z = d - t * 0.5;
    let top = if b.terrace == 1 || b.terrace == 2 { ph + 0.1 } else { 1.0 };
    g.cylinder(v(-hw + 0.02, top, z), v(hw - 0.02, top, z), 0.022, 8, true);
    let posts = if ph >= 0.9 { 1.2 } else { 0.12 };
    let n = ((w - 0.1) / posts).ceil().max(1.0) as i32;
    for i in 0..=n {
        let x = -hw + 0.05 + (w - 0.1) * i as f32 / n as f32;
        g.beam(v(x, ph.max(0.02), z), v(x, top, z), Vec3::X, 0.02, 0.02, 1.0);
    }
    if ph < 0.9 {
        g.cylinder(v(-hw + 0.02, ph + 0.06, z), v(hw - 0.02, ph + 0.06, z), 0.014, 6, false);
        for (on, x) in [(b.ends.0, -hw + 0.03), (b.ends.1, hw - 0.03)] {
            if on {
                g.cylinder(v(x, top, 0.02), v(x, top, z), 0.02, 6, false);
                let mut zz = 0.12;
                while zz < z - 0.05 {
                    g.beam(v(x, ph.max(0.02), zz), v(x, top, zz), Vec3::Z, 0.018, 0.018, 1.0);
                    zz += 0.12;
                }
            }
        }
    }
    if let Some(a) = b.awning {
        awning(p, a, w - 0.1, h_window + 0.3, d + 0.25, h_window - 0.5);
    }
}

/// Flower pots on a balcony slab and hanging on its railing.
pub fn pots(b: &BalconyKey) -> P {
    let mut p = P::new();
    let w = b.width_cm as f32 / 100.0;
    let d = b.depth_cm as f32 / 100.0;
    let hw = w * 0.5;
    let zf = d - 0.03;
    let mut rng = Rng::new(b.pots as u64 * 7919 + b.width_cm as u64);
    let count = 1 + rng.below(3);
    for k in 0..count {
        let x = -hw + 0.25 + (w - 0.5) * (k as f32 + rng.range(0.2, 0.8)) / count as f32;
        if rng.chance(0.5) {
            flower_pot(&mut p, v(x, 0.0, d * 0.55), 1.0, &mut rng);
        } else {
            // Hanging over the railing, the Madrid way.
            flower_pot(&mut p, v(x, 0.82, zf + 0.16), 0.8, &mut rng);
        }
    }
    p
}

/// Fabric awning from the wall (`top` height) out to `reach`, front edge at
/// `low`.
fn awning(p: &mut P, variant: u8, w: f32, top: f32, reach: f32, low: f32) {
    let m = Mat::Awning(variant);
    let hw = w * 0.5;
    let slope = (Vec2::new(reach, top - low)).length();
    let prim = p.get(m);
    prim.quad_uv([v(-hw, low, reach), v(hw, low, reach), v(hw, top, 0.03), v(-hw, top, 0.03)], [Vec2::new(0.0, slope), Vec2::new(w, slope), Vec2::new(w, 0.0), Vec2::ZERO]);
    prim.quad_uv([v(-hw, low - 0.22, reach + 0.01), v(hw, low - 0.22, reach + 0.01), v(hw, low, reach + 0.01), v(-hw, low, reach + 0.01)], [Vec2::new(0.0, 0.25), Vec2::new(w, 0.25), Vec2::new(w, 0.0), Vec2::ZERO]);
    let arm = p.get(Mat::Iron);
    for x in [-hw + 0.05, hw - 0.05] {
        arm.beam(v(x, top - 0.9, 0.02), v(x, low + 0.02, reach - 0.02), Vec3::X, 0.02, 0.02, 1.0);
    }
}

/// Terracotta pot with a geranium.
pub fn flower_pot(p: &mut P, at: Vec3, s: f32, rng: &mut Rng) {
    let pot = [(0.0, 0.0), (0.075, 0.0), (0.1, 0.17), (0.115, 0.17), (0.115, 0.2), (0.095, 0.2)];
    let pot: Vec<(f32, f32)> = pot.iter().map(|(r, y)| (r * s, y * s)).collect();
    p.get(Mat::Terracotta).lathe(at, &pot, 10);
    let r = rng.range(0.13, 0.2) * s;
    let blob: Vec<(f32, f32)> = (0..=6).map(|i| {
        let a = -std::f32::consts::FRAC_PI_2 + std::f32::consts::PI * i as f32 / 6.0;
        (a.cos() * r * if i == 0 || i == 6 { 0.0 } else { 1.0 }, 0.17 * s + r + a.sin() * r * 0.8)
    })
    .collect();
    p.get(Mat::Leaves).lathe(at, &blob, 7);
    let colors = [hex(0xd3202a), hex(0xe8467c), hex(0xf2f0ea), hex(0xc2185b), hex(0xff6f3c)];
    let col = *rng.pick(&colors);
    let f = p.get(Mat::Flowers(col));
    for _ in 0..7 {
        let a = rng.range(0.0, std::f32::consts::TAU);
        let e = rng.range(0.2, 1.2);
        let c = at + v(a.cos() * e.cos() * r, 0.17 * s + r + e.sin() * r * 0.8, a.sin() * e.cos() * r);
        f.aabox(c - Vec3::splat(0.03 * s), c + Vec3::splat(0.03 * s), 1.0);
    }
}

/// Glazed tribune (mirador) projecting from the facade.
fn mirador(p: &mut P, frame: Mat, base: Mat, w: f32, height: f32) {
    let d = 0.8;
    let hw = w * 0.5 + 0.45;
    bx(p, base, v(-hw - 0.05, -0.18, 0.0), v(hw + 0.05, 0.0, d + 0.05));
    for x in [-hw + 0.2, hw - 0.2] {
        bx(p, base, v(x - 0.07, -0.6, 0.0), v(x + 0.07, -0.18, d * 0.6));
    }
    let top = height;
    // Parapet panels.
    bx(p, frame, v(-hw, 0.0, d - 0.05), v(hw, 0.9, d));
    bx(p, frame, v(-hw, 0.0, 0.0), v(-hw + 0.05, 0.9, d));
    bx(p, frame, v(hw - 0.05, 0.0, 0.0), v(hw, 0.9, d));
    bx(p, frame, v(-hw, 0.9, d - 0.07), v(hw, 0.97, d + 0.01));
    bx(p, frame, v(-hw, top - 0.32, d - 0.06), v(hw, top, d + 0.01));
    // Posts.
    let n = ((2.0 * hw) / 0.62).round().max(2.0) as i32;
    for i in 0..=n {
        let x = -hw + 2.0 * hw * i as f32 / n as f32;
        bx(p, frame, v(x - 0.035, 0.0, d - 0.065), v(x + 0.035, top, d + 0.005));
    }
    for x in [-hw, hw - 0.06] {
        bx(p, frame, v(x, 0.0, 0.0), v(x + 0.06, top, 0.06));
        bx(p, frame, v(x, 0.0, d * 0.5 - 0.03), v(x + 0.06, top, d * 0.5 + 0.03));
    }
    let g = p.get(Mat::Glass);
    let (y0, y1) = (0.97, top - 0.32);
    let uv = [Vec2::new(0.0, 1.0), Vec2::new(1.0, 1.0), Vec2::new(1.0, 0.0), Vec2::ZERO];
    g.quad_uv([v(-hw, y0, d - 0.04), v(hw, y0, d - 0.04), v(hw, y1, d - 0.04), v(-hw, y1, d - 0.04)], uv);
    g.quad_uv([v(-hw + 0.03, y0, 0.0), v(-hw + 0.03, y0, d), v(-hw + 0.03, y1, d), v(-hw + 0.03, y1, 0.0)], uv);
    g.quad_uv([v(hw - 0.03, y0, d), v(hw - 0.03, y0, 0.0), v(hw - 0.03, y1, 0.0), v(hw - 0.03, y1, d)], uv);
    bx(p, base, v(-hw - 0.08, top, 0.0), v(hw + 0.08, top + 0.1, d + 0.08));
    bx(p, base, v(-hw - 0.12, top + 0.1, 0.0), v(hw + 0.12, top + 0.16, d + 0.12));
}

/// Everything needed to build one window/balcony-door module.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct WindowKey {
    pub w_cm: u16,
    pub h_cm: u16,
    /// Door to a balcony (opening reaches the floor).
    pub door: bool,
    pub surround: Mat,
    pub surround_kind: SurroundKind,
    pub frame: Rgb,
    pub shutter: Option<(ShutterKind, Rgb, u8)>,
    pub balcony: Option<BalconyKey>,
    /// Mirador height in cm (replaces the balcony).
    pub mirador: Option<u16>,
    pub interior: u8,
    pub grille: bool,
}

/// Separately instanced pieces of an opening, so variants combine at
/// placement time instead of multiplying into unique meshes.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Piece {
    /// Stone surround, sill and grille.
    Surround,
    /// Joinery and glass (and the mirador built from the same joinery).
    Glazing,
    /// Fake room behind the glass.
    Interior,
    Shutter,
    Balcony,
}

impl Piece {
    pub const ALL: [Piece; 5] = [Piece::Surround, Piece::Glazing, Piece::Interior, Piece::Shutter, Piece::Balcony];
}

impl WindowKey {
    /// The key reduced to what `piece` depends on.
    pub fn for_piece(&self, piece: Piece) -> WindowKey {
        let blank = WindowKey { w_cm: self.w_cm, h_cm: self.h_cm, door: self.door, surround: Mat::Iron, surround_kind: SurroundKind::None, frame: [0; 3], shutter: None, balcony: None, mirador: None, interior: 0, grille: false };
        let has_balcony = self.balcony.map(|_| BalconyKey { width_cm: 0, depth_cm: 0, belly: false, ends: (false, false), pots: 0, awning: None, terrace: 0 });
        match piece {
            Piece::Surround => WindowKey { surround: self.surround, surround_kind: self.surround_kind, balcony: has_balcony, grille: self.grille, ..blank },
            Piece::Glazing => WindowKey { frame: self.frame, mirador: self.mirador, surround: if self.mirador.is_some() { self.surround } else { Mat::Iron }, ..blank },
            Piece::Interior => WindowKey { interior: self.interior, ..blank },
            Piece::Shutter => WindowKey {
                shutter: self.shutter,
                balcony: if self.mirador.is_some() { None } else { self.balcony.map(|b| BalconyKey { width_cm: 0, depth_cm: b.depth_cm, belly: false, ends: (false, false), pots: 0, awning: None, terrace: 0 }) },
                ..blank
            },
            Piece::Balcony => WindowKey { surround: self.surround, balcony: if self.mirador.is_some() { None } else { self.balcony }, ..blank },
        }
    }
}

pub fn window(k: &WindowKey) -> P {
    let mut p = P::new();
    for piece in Piece::ALL {
        p.append(&window_piece(&k.for_piece(piece), piece), &Mat4::IDENTITY);
    }
    p
}

pub fn window_piece(k: &WindowKey, piece: Piece) -> P {
    let mut p = P::new();
    let (w, h) = (k.w_cm as f32 / 100.0, k.h_cm as f32 / 100.0);
    let frame = Mat::PaintedWood(k.frame);
    match piece {
        Piece::Surround => {
            surround(&mut p, k.surround, k.surround_kind, w, h, if k.door { 0.0 } else { -0.02 }, !k.door && k.balcony.is_none());
            if k.grille {
                grille(&mut p, w, h);
            }
        }
        Piece::Glazing => {
            glazing(&mut p, frame, w, h, k.door);
            if let Some(hcm) = k.mirador {
                mirador(&mut p, frame, k.surround, w, hcm as f32 / 100.0);
            }
        }
        // Interiors 4-7 are shallow rooms for thin lots.
        Piece::Interior => interior(&mut p, Mat::Interior, w, h, k.interior % 4, if k.interior >= 4 { 0.6 } else { 1.6 }),
        Piece::Balcony => {
            if let (Some(b), None) = (&k.balcony, k.mirador) {
                balcony(&mut p, k.surround, b, h);
            }
        }
        Piece::Shutter => {
            if let (Some((kind, c, state)), None) = (k.shutter, k.mirador) {
                match kind {
                    ShutterKind::Alicantina => {
                        let lowered = [0.35, 0.6, 0.85, 1.0][state as usize % 4];
                        alicantina(&mut p, Mat::Wood(c), w, h, lowered, k.balcony.map(|b| b.depth_cm as f32 / 100.0));
                    }
                    ShutterKind::Louvre => louvres(&mut p, Mat::PaintedWood(c), w - 0.02, h - 0.02, state),
                    ShutterKind::Roller => roller(&mut p, w - 0.02, h - 0.02, [0.2, 0.45, 0.7, 1.0][state as usize % 4]),
                }
            }
        }
    }
    p
}

/// Wrought-iron window grille (reja) with an arched top.
fn grille(p: &mut P, w: f32, h: f32) {
    let prim = p.get(Mat::Iron);
    let (hw, z) = (w * 0.5 + 0.08, 0.13);
    let n = ((2.0 * hw) / 0.11).round() as i32;
    for i in 0..=n {
        let x = -hw + 2.0 * hw * i as f32 / n as f32;
        prim.beam(v(x, -0.12, z), v(x, h + 0.05, z), Vec3::X, 0.018, 0.018, 1.0);
    }
    for y in [-0.1, h * 0.33, h * 0.66, h + 0.05] {
        prim.beam(v(-hw, y, z), v(hw, y, z), Vec3::Y, 0.02, 0.02, 1.0);
    }
    for y in [-0.1, h + 0.05] {
        for x in [-hw, hw] {
            prim.beam(v(x, y, 0.0), v(x, y, z), Vec3::Y, 0.02, 0.02, 1.0);
        }
    }
    // Arched crest with radial bars.
    let r = hw;
    let c = v(0.0, h + 0.05, z);
    let mut prev = c + v(r, 0.0, 0.0);
    for i in 1..=12 {
        let a = std::f32::consts::PI * i as f32 / 12.0;
        let q = c + v(a.cos() * r, a.sin() * r * 0.45, 0.0);
        prim.beam(prev, q, Vec3::Z, 0.018, 0.018, 1.0);
        if i % 3 == 0 && i < 12 {
            prim.beam(c, q, Vec3::Z, 0.014, 0.014, 1.0);
        }
        prev = q;
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct ShopKey {
    pub w_cm: u16,
    pub h_cm: u16,
    pub surround: Mat,
    pub sign: u8,
    /// Shutter lowered: 0 = open, 3 = closed.
    pub shutter: u8,
    pub graffiti: u8,
    pub frame: Rgb,
    pub awning: Option<u8>,
    pub interior: u8,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ShopPiece {
    /// Stone or tiled frame around the opening.
    Surround,
    /// Painted joinery, door and glass.
    Front,
    Interior,
    Sign,
    Shutter,
    Awning,
}

impl ShopPiece {
    pub const ALL: [ShopPiece; 6] = [ShopPiece::Surround, ShopPiece::Front, ShopPiece::Interior, ShopPiece::Sign, ShopPiece::Shutter, ShopPiece::Awning];
}

impl ShopKey {
    pub fn for_piece(&self, piece: ShopPiece) -> ShopKey {
        let blank = ShopKey { w_cm: self.w_cm, h_cm: self.h_cm, surround: Mat::Iron, sign: 0, shutter: 0, graffiti: 0, frame: [0; 3], awning: None, interior: 0 };
        match piece {
            ShopPiece::Surround => ShopKey { surround: self.surround, ..blank },
            ShopPiece::Front => ShopKey { frame: self.frame, sign: self.sign % 3, ..blank },
            ShopPiece::Interior => ShopKey { interior: self.sign % 4, ..blank },
            ShopPiece::Sign => ShopKey { sign: self.sign, ..blank },
            ShopPiece::Shutter => ShopKey { shutter: self.shutter, graffiti: if self.shutter == 3 { self.graffiti } else { 0 }, ..blank },
            ShopPiece::Awning => ShopKey { awning: self.awning, ..blank },
        }
    }
}

pub fn shop(k: &ShopKey) -> P {
    let mut p = P::new();
    for piece in ShopPiece::ALL {
        p.append(&shop_piece(&k.for_piece(piece), piece), &Mat4::IDENTITY);
    }
    p
}

pub fn shop_piece(k: &ShopKey, piece: ShopPiece) -> P {
    let mut p = P::new();
    let (w, h) = (k.w_cm as f32 / 100.0, k.h_cm as f32 / 100.0);
    let hw = w * 0.5;
    let sign_h = 0.55;
    let ys = h - sign_h;
    match piece {
        ShopPiece::Surround => {
            let (bw, pr) = (0.22, 0.05);
            bx(&mut p, k.surround, v(-hw - bw, 0.0, 0.0), v(-hw, h, pr));
            bx(&mut p, k.surround, v(hw, 0.0, 0.0), v(hw + bw, h, pr));
            bx(&mut p, k.surround, v(-hw - bw, h, 0.0), v(hw + bw, h + 0.18, pr + 0.02));
        }
        ShopPiece::Interior => interior(&mut p, Mat::ShopInterior, w, ys, k.interior, 4.0),
        ShopPiece::Front => {
            let frame = Mat::PaintedWood(k.frame);
            bx(&mut p, frame, v(-hw, ys - 0.06, -0.08), v(hw, ys, -0.02));
            // Shopfront: kick plate, mullions, door.
            let z = -0.24;
            bx(&mut p, frame, v(-hw, 0.0, z - 0.03), v(hw, 0.35, z + 0.03));
            let door_x = if k.sign % 3 == 0 { 0.0 } else if k.sign % 3 == 1 { -hw + 0.7 } else { hw - 0.7 };
            for x in [-hw + 0.03, hw - 0.03, door_x - 0.52, door_x + 0.52] {
                bx(&mut p, frame, v(x - 0.04, 0.0, z - 0.04), v(x + 0.04, ys - 0.06, z + 0.04));
            }
            bx(&mut p, frame, v(-hw, ys - 0.12, z - 0.03), v(hw, ys - 0.06, z + 0.03));
            // The door itself: glazed leaf with a push bar.
            bx(&mut p, frame, v(door_x - 0.48, 0.0, z - 0.02), v(door_x + 0.48, 0.08, z + 0.02));
            bx(&mut p, Mat::Galvanized, v(door_x - 0.3, 1.0, z + 0.02), v(door_x + 0.3, 1.04, z + 0.06));
            let g = p.get(Mat::Glass);
            let uv = [Vec2::new(0.0, 1.0), Vec2::new(1.0, 1.0), Vec2::new(1.0, 0.0), Vec2::ZERO];
            g.quad_uv([v(-hw, 0.08, z - 0.01), v(hw, 0.08, z - 0.01), v(hw, ys - 0.12, z - 0.01), v(-hw, ys - 0.12, z - 0.01)], uv);
        }
        ShopPiece::Sign => {
            let row = (k.sign % 16) as f32;
            let sgn = p.get(Mat::ShopSign);
            sgn.quad_uv([v(-hw, ys, -0.06), v(hw, ys, -0.06), v(hw, h, -0.06), v(-hw, h, -0.06)], [Vec2::new(0.0, (row + 1.0) / 16.0), Vec2::new(1.0, (row + 1.0) / 16.0), Vec2::new(1.0, row / 16.0), Vec2::new(0.0, row / 16.0)]);
        }
        ShopPiece::Shutter => {
            if k.shutter > 0 {
                let lowered = [0.0, 0.3, 0.65, 1.0][k.shutter as usize % 4];
                let yb = ys - lowered * ys;
                let m = Mat::MetalShutter(if k.shutter == 3 { k.graffiti } else { 0 });
                let s = p.get(m);
                let uv = [Vec2::new(0.0, (ys - yb) / ys), Vec2::new(1.0, (ys - yb) / ys), Vec2::new(1.0, 0.0), Vec2::ZERO];
                s.quad_uv([v(-hw, yb, -0.1), v(hw, yb, -0.1), v(hw, ys, -0.1), v(-hw, ys, -0.1)], uv);
                bx(&mut p, Mat::Iron, v(-hw, yb - 0.05, -0.12), v(hw, yb, -0.08));
            }
        }
        ShopPiece::Awning => {
            if let Some(a) = k.awning {
                awning(&mut p, a, w + 0.2, h + 0.12, 1.3, h - 0.55);
            }
        }
    }
    p
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct PortalKey {
    pub w_cm: u16,
    pub h_cm: u16,
    pub surround: Mat,
    pub door: Rgb,
}

/// Arched main entrance with a double wooden door and a fanlight.
pub fn portal(k: &PortalKey) -> P {
    let mut p = P::new();
    let (w, h) = (k.w_cm as f32 / 100.0, k.h_cm as f32 / 100.0);
    let r = w * 0.5;
    let ys = h - r;
    let (bw, pr) = (0.24, 0.05);
    let m = k.surround;
    bx(&mut p, m, v(-r - bw, 0.0, 0.0), v(-r, ys, pr));
    bx(&mut p, m, v(r, 0.0, 0.0), v(r + bw, ys, pr));
    // Plinth blocks at the base of the jambs.
    bx(&mut p, m, v(-r - bw - 0.03, 0.0, 0.0), v(-r, 0.5, pr + 0.03));
    bx(&mut p, m, v(r, 0.0, 0.0), v(r + bw + 0.03, 0.5, pr + 0.03));
    let s = m.scale();
    {
        let prim = p.get(m);
        let n = 11;
        let c = v(0.0, ys, 0.0);
        for i in 0..n {
            let (a0, a1) = (std::f32::consts::PI * i as f32 / n as f32, std::f32::consts::PI * (i + 1) as f32 / n as f32);
            let dir = |a: f32| v(a.cos(), a.sin(), 0.0);
            let key = i == n / 2;
            let (ri, ro, z) = (r, r + bw + if key { 0.12 } else { 0.0 }, pr + if key { 0.04 } else { 0.0 });
            let (i0, i1, o0, o1) = (c + dir(a0) * ri, c + dir(a1) * ri, c + dir(a0) * ro, c + dir(a1) * ro);
            let zf = Vec3::Z * z;
            prim.quad(o0 + zf, i0 + zf, i1 + zf, o1 + zf, s);
            prim.quad(i0 + zf, i0, i1, i1 + zf, s);
            prim.quad(o1 + zf, o1, o0, o0 + zf, s);
            // Spandrels fill the rectangular hole above the arch.
            let corner = if (a0 + a1) * 0.5 < std::f32::consts::FRAC_PI_2 { v(r, h, -0.02) } else { v(-r, h, -0.02) };
            let (q0, q1) = (i0 - Vec3::Z * 0.02, i1 - Vec3::Z * 0.02);
            prim.tri(q0, corner, q1, [Vec2::ZERO, Vec2::new(0.5, 1.0), Vec2::new(1.0, 0.0)]);
        }
    }
    // Doors.
    let door = Mat::PaintedWood(k.door);
    let z = -0.26;
    for (x0, x1) in [(-r, -0.005), (0.005, r)] {
        bx(&mut p, door, v(x0, 0.0, z - 0.04), v(x1, ys, z));
        let pw = x1 - x0;
        for (y0, y1) in [(0.15, ys * 0.42), (ys * 0.48, ys - 0.12)] {
            bx(&mut p, door, v(x0 + pw * 0.15, y0, z), v(x1 - pw * 0.15, y1, z + 0.025));
            bx(&mut p, door, v(x0 + pw * 0.22, y0 + 0.07, z + 0.025), v(x1 - pw * 0.22, y1 - 0.07, z + 0.04));
        }
    }
    bx(&mut p, Mat::Galvanized, v(-0.09, ys * 0.5, z), v(-0.03, ys * 0.5 + 0.18, z + 0.06));
    bx(&mut p, Mat::Galvanized, v(0.03, ys * 0.5, z), v(0.09, ys * 0.5 + 0.18, z + 0.06));
    bx(&mut p, door, v(-r, ys - 0.06, z - 0.05), v(r, ys + 0.04, z + 0.02));
    // Fanlight glass and its radial iron bars.
    let c = v(0.0, ys + 0.04, z - 0.01);
    {
        let g = p.get(Mat::Glass);
        let n = 12;
        for i in 0..n {
            let (a0, a1) = (std::f32::consts::PI * i as f32 / n as f32, std::f32::consts::PI * (i + 1) as f32 / n as f32);
            g.tri(c, c + v(a0.cos(), a0.sin(), 0.0) * (r - 0.02), c + v(a1.cos(), a1.sin(), 0.0) * (r - 0.02), [Vec2::ZERO, Vec2::X, Vec2::Y]);
        }
    }
    {
        let iron = p.get(Mat::Iron);
        for i in 1..6 {
            let a = std::f32::consts::PI * i as f32 / 6.0;
            iron.beam(c + Vec3::Z * 0.02, c + v(a.cos(), a.sin(), 0.0) * (r - 0.02) + Vec3::Z * 0.02, Vec3::Z, 0.02, 0.02, 1.0);
        }
    }
    p.get(Mat::Interior).quad_uv([v(-r, ys, -1.2), v(r, ys, -1.2), v(r, h, -1.2), v(-r, h, -1.2)], [Vec2::new(0.02, 0.3), Vec2::new(0.23, 0.3), Vec2::new(0.23, 0.05), Vec2::new(0.02, 0.05)]);
    p
}

// ---------------------------------------------------------------- roofline

/// One meter of stone balustrade along +X, centred on the parapet line.
pub fn balustrade(m: Mat) -> P {
    let mut p = P::new();
    bx(&mut p, m, v(-0.5, 0.0, -0.16), v(0.5, 0.16, 0.16));
    bx(&mut p, m, v(-0.5, 0.72, -0.17), v(0.5, 0.84, 0.17));
    bx(&mut p, m, v(-0.5, 0.84, -0.19), v(0.5, 0.88, 0.19));
    let prof = [(0.05, 0.16), (0.06, 0.19), (0.045, 0.25), (0.05, 0.3), (0.085, 0.42), (0.075, 0.5), (0.04, 0.61), (0.035, 0.65), (0.055, 0.68), (0.06, 0.72)];
    for x in [-0.375, -0.125, 0.125, 0.375] {
        p.get(m).lathe(v(x, 0.0, 0.0), &prof, 8);
    }
    p
}

/// Pedestal on the parapet with an urn (`urn`) or a ball pinnacle.
pub fn pedestal(m: Mat, urn: bool) -> P {
    let mut p = P::new();
    bx(&mut p, m, v(-0.22, 0.0, -0.22), v(0.22, 0.92, 0.22));
    bx(&mut p, m, v(-0.26, 0.92, -0.26), v(0.26, 1.0, 0.26));
    let prof: &[(f32, f32)] = if urn {
        &[(0.0, 1.0), (0.1, 1.0), (0.12, 1.05), (0.07, 1.12), (0.15, 1.24), (0.2, 1.38), (0.17, 1.5), (0.11, 1.54), (0.14, 1.58), (0.06, 1.62), (0.04, 1.7), (0.0, 1.74)]
    } else {
        &[(0.0, 1.0), (0.12, 1.0), (0.12, 1.08), (0.06, 1.14), (0.05, 1.5), (0.03, 1.56), (0.09, 1.62), (0.11, 1.7), (0.09, 1.79), (0.0, 1.82)]
    };
    p.get(m).lathe(Vec3::ZERO, prof, 10);
    p
}

/// Central crest (coronamiento) rising over the cornice: segmental
/// pediment with an oval tile medallion and finials.
pub fn crest(m: Mat, tiles: Mat, w: f32) -> P {
    let mut p = P::new();
    let hw = w * 0.5;
    let mut outline = vec![Vec2::new(-hw, 0.0), Vec2::new(hw, 0.0), Vec2::new(hw, 0.85)];
    for i in 1..12 {
        let t = i as f32 / 12.0;
        let x = hw - 2.0 * hw * t;
        outline.push(Vec2::new(x, 0.85 + 0.75 * (1.0 - (x / hw).powi(2)).sqrt()));
    }
    outline.push(Vec2::new(-hw, 0.85));
    p.get(m).extrude_xy(&outline, -0.15, 0.15, m.scale(), |q| q / m.scale());
    p.get(m).sweep(&[v(-hw - 0.1, 0.0, 0.0), v(hw + 0.1, 0.0, 0.0)], &[Vec3::Z, Vec3::Z], &[(0.15, 0.85), (0.24, 0.88), (0.24, 0.96), (0.15, 0.98)], false, true, 1.0);
    let oval: Vec<Vec2> = (0..20).map(|i| {
        let a = std::f32::consts::TAU * i as f32 / 20.0;
        Vec2::new(a.cos() * w * 0.16, 0.95 + a.sin() * 0.3)
    })
    .collect();
    p.get(tiles).extrude_xy(&oval, 0.15, 0.19, 0.6, |q| q / 0.6);
    let ring: Vec<Vec2> = oval.iter().map(|q| Vec2::new(q.x * 1.18, 0.95 + (q.y - 0.95) * 1.2)).collect();
    p.get(m).extrude_xy(&ring, 0.15, 0.17, 1.0, |q| q);
    let finial = [(0.0, 0.0), (0.09, 0.0), (0.09, 0.08), (0.05, 0.14), (0.08, 0.26), (0.05, 0.36), (0.0, 0.42)];
    for (x, y) in [(-hw, 0.85), (hw, 0.85), (0.0, 1.6)] {
        p.get(m).lathe(v(x, y, 0.0), &finial, 8);
    }
    p
}

/// Dormer window (buhardilla) set into a roof; front at local z = 0.
pub fn dormer(wall: Mat, roof: Mat, frame: Rgb) -> P {
    let mut p = P::new();
    let (wd, hd, dd) = (1.5, 1.55, 1.8);
    let hw = wd * 0.5;
    let (ww, wh, wy) = (0.8, 1.05, 0.25);
    bx(&mut p, wall, v(-hw, 0.0, -dd), v(-ww * 0.5, hd, 0.0));
    bx(&mut p, wall, v(ww * 0.5, 0.0, -dd), v(hw, hd, 0.0));
    bx(&mut p, wall, v(-ww * 0.5, 0.0, -dd), v(ww * 0.5, wy, 0.0));
    bx(&mut p, wall, v(-ww * 0.5, wy + wh, -dd), v(ww * 0.5, hd, 0.0));
    let mut win = P::new();
    glazing(&mut win, Mat::PaintedWood(frame), ww, wh, false);
    interior(&mut win, Mat::Interior, ww, wh, 2, 0.8);
    p.append(&win, &Mat4::from_translation(v(0.0, wy, 0.0)));
    let ridge = hd + 0.6;
    let s = roof.scale();
    let r = p.get(roof);
    let (e, zf, zb) = (hw + 0.12, 0.12, -dd);
    r.quad(v(-e, hd - 0.06, zf), v(0.0, ridge, zf), v(0.0, ridge, zb), v(-e, hd - 0.06, zb), s);
    r.quad(v(0.0, ridge, zf), v(e, hd - 0.06, zf), v(e, hd - 0.06, zb), v(0.0, ridge, zb), s);
    let g = p.get(wall);
    g.tri(v(-hw, hd, 0.0), v(hw, hd, 0.0), v(0.0, ridge - 0.04, 0.0), [Vec2::ZERO, Vec2::new(1.0, 0.0), Vec2::new(0.5, 0.4)]);
    p
}

/// Brick or stucco chimney with a cap.
pub fn chimney(m: Mat) -> P {
    let mut p = P::new();
    bx(&mut p, m, v(-0.35, 0.0, -0.25), v(0.35, 1.4, 0.25));
    bx(&mut p, m, v(-0.42, 1.4, -0.32), v(0.42, 1.48, 0.32));
    for x in [-0.3, 0.3] {
        bx(&mut p, m, v(x - 0.06, 1.48, -0.06), v(x + 0.06, 1.68, 0.06));
    }
    bx(&mut p, m, v(-0.42, 1.68, -0.32), v(0.42, 1.74, 0.32));
    p
}

/// Rooftop clutter: water tank, AC unit, TV aerial or stair house.
pub fn rooftop(kind: u8, wall: Mat) -> P {
    let mut p = P::new();
    match kind % 4 {
        0 => {
            p.get(Mat::Plastic(hex(0xe8e6df))).cylinder(v(-0.6, 0.6, 0.0), v(0.6, 0.6, 0.0), 0.5, 14, true);
            bx(&mut p, Mat::Galvanized, v(-0.5, 0.0, -0.4), v(-0.42, 0.2, 0.4));
            bx(&mut p, Mat::Galvanized, v(0.42, 0.0, -0.4), v(0.5, 0.2, 0.4));
        }
        1 => {
            bx(&mut p, Mat::Plastic(hex(0xf2f2ee)), v(-0.45, 0.0, -0.18), v(0.45, 0.65, 0.18));
            p.get(Mat::Iron).cylinder(v(0.1, 0.33, 0.18), v(0.1, 0.33, 0.19), 0.24, 16, true);
        }
        2 => {
            let g = p.get(Mat::Galvanized);
            g.cylinder(v(0.0, 0.0, 0.0), v(0.0, 3.2, 0.0), 0.025, 6, false);
            for (k, y) in [2.4f32, 2.7, 3.0].iter().enumerate() {
                let l = 0.9 - k as f32 * 0.2;
                g.beam(v(-l * 0.5, *y, 0.0), v(l * 0.5, *y, 0.0), Vec3::Y, 0.015, 0.015, 1.0);
                g.beam(v(0.0, *y, -0.4), v(0.0, *y, 0.4), Vec3::Y, 0.012, 0.012, 1.0);
            }
            g.cylinder(v(0.0, 1.5, 0.0), v(0.45, 1.5, 0.0), 0.012, 4, false);
            p.get(Mat::Plastic(hex(0xdcdcd6))).cylinder(v(0.45, 1.5, -0.02), v(0.45, 1.5, 0.08), 0.32, 14, true);
        }
        _ => {
            bx(&mut p, wall, v(-1.3, 0.0, -1.6), v(1.3, 2.5, 1.6));
            bx(&mut p, Mat::Moulding(hex(0xeeeeea)), v(-1.38, 2.5, -1.68), v(1.38, 2.62, 1.68));
            bx(&mut p, Mat::PaintedWood(hex(0x6b4a2e)), v(-0.45, 0.0, 1.6), v(0.45, 2.05, 1.63));
        }
    }
    p
}

/// Rooftop TV aerial: a galvanised mast on a tripod foot with one or two
/// UHF Yagis pointing along +Z (towards the transmitter) and, on some, a
/// bow-tie or FM dipole near the top. Origin at the foot of the mast.
pub fn tv_antenna(variant: u8) -> P {
    let mut p = P::new();
    let h = [3.4f32, 4.3, 2.8][variant as usize % 3];
    let g = p.get(Mat::Galvanized);
    g.cylinder(v(0.0, 0.0, 0.0), v(0.0, h, 0.0), 0.024, 6, true);
    for k in 0..3 {
        let a = std::f32::consts::TAU * k as f32 / 3.0 + 0.4;
        g.beam(v(0.0, 0.55, 0.0), v(a.cos() * 0.5, 0.0, a.sin() * 0.5), Vec3::Y, 0.02, 0.02, 1.0);
    }
    // Yagi: boom along +Z, directors across, a reflector grid at the back.
    let yagi = |g: &mut Prim, y: f32, len: f32, n: i32| {
        let z0 = -0.22;
        g.beam(v(0.0, y, z0), v(0.0, y, z0 + len), Vec3::Y, 0.02, 0.02, 1.0);
        g.beam(v(0.0, y - 0.04, 0.0), v(0.0, y + 0.04, 0.0), Vec3::X, 0.05, 0.05, 1.0);
        for i in 0..n {
            let z = z0 + 0.2 + (len - 0.2) * i as f32 / (n - 1) as f32;
            let half = 0.15 - 0.05 * i as f32 / n as f32;
            g.beam(v(-half, y, z), v(half, y, z), Vec3::Y, 0.008, 0.008, 1.0);
        }
        for k in 0..4 {
            let yy = y - 0.22 + k as f32 * 0.147;
            g.beam(v(-0.24, yy, z0), v(0.24, yy, z0), Vec3::Y, 0.008, 0.008, 1.0);
        }
        g.beam(v(0.0, y - 0.24, z0), v(0.0, y + 0.24, z0), Vec3::X, 0.012, 0.012, 1.0);
    };
    yagi(g, h - 0.35, if variant % 2 == 0 { 1.5 } else { 1.1 }, 12);
    if variant % 3 != 2 {
        yagi(g, h - 1.15, 0.9, 8);
    }
    if variant % 2 == 1 {
        // FM dipole across the top.
        g.beam(v(-0.75, h - 0.05, 0.0), v(0.75, h - 0.05, 0.0), Vec3::Y, 0.012, 0.012, 1.0);
    }
    // Amplifier box and the coax down the mast.
    bx(&mut p, Mat::Plastic(hex(0xdcdad2)), v(-0.06, 1.25, 0.03), v(0.06, 1.42, 0.09));
    p.get(Mat::Plastic(hex(0x1e1e1e))).beam(v(0.03, 0.0, 0.03), v(0.03, h - 0.4, 0.03), Vec3::X, 0.008, 0.008, 1.0);
    p
}

/// One metre of terrace railing along +X on top of a parapet: square
/// posts, a flat top rail and plain bars (the 1960s-80s ático kind).
pub fn terrace_railing() -> P {
    let mut p = P::new();
    let iron = Mat::Iron;
    bx(&mut p, iron, v(-0.5, 0.0, -0.025), v(0.5, 0.03, 0.025));
    bx(&mut p, iron, v(-0.5, 0.6, -0.035), v(0.5, 0.64, 0.035));
    bx(&mut p, iron, v(-0.5, 0.5, -0.012), v(0.5, 0.52, 0.012));
    bx(&mut p, iron, v(-0.5, 0.0, -0.025), v(-0.45, 0.64, 0.025));
    let prim = p.get(iron);
    for k in 1..9 {
        let x = -0.5 + k as f32 * 0.111;
        prim.beam(v(x, 0.03, 0.0), v(x, 0.6, 0.0), Vec3::X, 0.014, 0.014, 1.0);
    }
    p
}

/// Terrace planting seen over an ático railing: a planter of box shrubs,
/// a potted olive or a jasmine climbing a trellis. Origin at the foot.
pub fn planter(variant: u8) -> P {
    let mut p = P::new();
    let mut rng = Rng::new(variant as u64 * 4211 + 3);
    let blob = |p: &mut P, at: Vec3, r: f32, hgt: f32| {
        let prof: Vec<(f32, f32)> = (0..=6)
            .map(|i| {
                let a = -std::f32::consts::FRAC_PI_2 + std::f32::consts::PI * i as f32 / 6.0;
                (if i == 0 || i == 6 { 0.0 } else { a.cos() * r }, hgt * (0.5 + a.sin() * 0.5))
            })
            .collect();
        p.get(Mat::Leaves).lathe(at, &prof, 8);
    };
    match variant % 3 {
        0 => {
            bx(&mut p, Mat::Terracotta, v(-0.5, 0.0, -0.2), v(0.5, 0.42, 0.2));
            for x in [-0.28, 0.0, 0.28] {
                let r = rng.range(0.22, 0.3);
                blob(&mut p, v(x, 0.3, 0.0), r, rng.range(0.7, 1.0));
            }
        }
        1 => {
            p.get(Mat::Terracotta).lathe(Vec3::ZERO, &[(0.0, 0.0), (0.2, 0.0), (0.27, 0.5), (0.3, 0.52), (0.3, 0.56), (0.0, 0.56)], 12);
            p.get(Mat::Wood(hex(0x5a4632))).cylinder(v(0.0, 0.5, 0.0), v(0.05, 1.5, 0.02), 0.045, 6, false);
            for (dx, dy, r) in [(0.0, 1.45, 0.42), (0.25, 1.75, 0.3), (-0.22, 1.7, 0.32)] {
                blob(&mut p, v(dx, dy, 0.0), r, r * 1.5);
            }
        }
        _ => {
            bx(&mut p, Mat::Terracotta, v(-0.4, 0.0, -0.18), v(0.4, 0.38, 0.18));
            let g = p.get(Mat::Wood(hex(0x6a5038)));
            for x in [-0.35, 0.35] {
                g.beam(v(x, 0.3, -0.05), v(x, 1.9, -0.05), Vec3::X, 0.03, 0.03, 1.0);
            }
            for (dx, dy, r) in [(-0.2, 0.3, 0.3), (0.15, 0.6, 0.32), (-0.1, 1.05, 0.3), (0.12, 1.4, 0.26)] {
                blob(&mut p, v(dx, dy, 0.0), r, r * 1.8);
            }
            let f = p.get(Mat::Flowers(hex(0xf6f4ee)));
            for _ in 0..24 {
                let c = v(rng.range(-0.4, 0.4), rng.range(0.5, 1.8), rng.range(0.1, 0.3));
                f.aabox(c - Vec3::splat(0.025), c + Vec3::splat(0.025), 1.0);
            }
        }
    }
    p
}

// ------------------------------------------------------------ lived-in clutter

/// Split AC condenser (the white box on every Spanish facade). Origin at
/// the bottom centre against the wall; `bracket` hangs it on steel
/// brackets, otherwise it stands on rubber feet (balcony floor).
pub fn ac_unit(bracket: bool, variant: u8) -> P {
    let mut p = P::new();
    let (w, h, z0, z1) = if variant % 2 == 0 { (0.8, 0.55, 0.06, 0.34) } else { (0.7, 0.5, 0.06, 0.31) };
    let hw = w * 0.5;
    let shell = Mat::Plastic(if variant % 3 == 2 { hex(0xd9d6cc) } else { hex(0xeeece6) });
    bx(&mut p, shell, v(-hw, 0.0, z0), v(hw, h, z1));
    // Fan opening: dark disc behind a grille, offset to the left.
    let fc = v(-hw + 0.3, h * 0.5, z1);
    p.get(Mat::Iron).cylinder(fc + v(0.0, 0.0, -0.01), fc + v(0.0, 0.0, 0.002), 0.2, 20, true);
    {
        let g = p.get(Mat::Galvanized);
        for k in -3..=3 {
            let x = k as f32 * 0.055;
            let r = (0.2f32 * 0.2 - x * x).max(0.0).sqrt();
            g.beam(fc + v(x, -r, 0.006), fc + v(x, r, 0.006), Vec3::Z, 0.006, 0.006, 1.0);
        }
        g.beam(fc + v(-0.2, 0.0, 0.008), fc + v(0.2, 0.0, 0.008), Vec3::Z, 0.008, 0.008, 1.0);
    }
    // Louvred side and the service valve cover on the right.
    for k in 0..6 {
        let y = 0.08 + k as f32 * 0.065;
        bx(&mut p, shell, v(hw - 0.2, y, z1), v(hw - 0.04, y + 0.03, z1 + 0.012));
    }
    bx(&mut p, Mat::Plastic(hex(0xc8c6be)), v(hw, 0.08, z0 + 0.05), v(hw + 0.02, 0.3, z1 - 0.03));
    // Refrigerant lines in a white trunking up the wall, with the drip.
    let duct = Mat::Plastic(hex(0xe4e2da));
    bx(&mut p, duct, v(hw + 0.02, 0.18, 0.0), v(hw + 0.1, 0.24, z0 + 0.1));
    bx(&mut p, duct, v(hw + 0.04, 0.18, 0.0), v(hw + 0.1, 1.1, 0.05));
    p.get(Mat::Plastic(hex(0x2a2a2a))).beam(v(-hw + 0.06, 0.0, z0 + 0.04), v(-hw + 0.06, -0.12, z0 + 0.06), Vec3::X, 0.014, 0.014, 1.0);
    if bracket {
        for x in [-hw + 0.1, hw - 0.1] {
            let g = p.get(Mat::Galvanized);
            g.beam(v(x, -0.02, 0.0), v(x, -0.02, z1 + 0.04), Vec3::X, 0.035, 0.035, 1.0);
            g.beam(v(x, -0.4, 0.0), v(x, -0.02, z1 - 0.04), Vec3::X, 0.03, 0.03, 1.0);
            g.beam(v(x, -0.42, 0.0), v(x, 0.05, 0.0), Vec3::Z, 0.04, 0.012, 1.0);
        }
    } else {
        for x in [-hw + 0.08, hw - 0.08] {
            bx(&mut p, Mat::Plastic(hex(0x202020)), v(x - 0.04, -0.06, z0 + 0.02), v(x + 0.04, 0.0, z1 - 0.02));
        }
    }
    p
}

/// Satellite dish on a wall arm, aimed up and to the south-ish.
pub fn dish(variant: u8) -> P {
    let mut p = P::new();
    let r = if variant % 2 == 0 { 0.32 } else { 0.4 };
    let depth = r * r / 1.6;
    // Closed thin shell: convex back going out, concave face coming back.
    let n = 6;
    let mut prof: Vec<(f32, f32)> = (0..=n).map(|i| {
        let t = i as f32 / n as f32 * r;
        (t, t * t / 1.6)
    })
    .collect();
    prof.push((r, depth + 0.012));
    prof.extend((0..n).rev().map(|i| {
        let t = i as f32 / n as f32 * r;
        (t, t * t / 1.6 + 0.012)
    }));
    let mut bowl = P::new();
    let col = if variant % 3 == 1 { hex(0x9fa3a6) } else { hex(0xe6e6e2) };
    bowl.get(Mat::Plastic(col)).lathe(Vec3::ZERO, &prof, 18);
    // LNB arm from the lower rim to the focus (y = 0.4), and the LNB.
    let focus = v(0.0, 0.4, 0.0);
    bowl.get(Mat::Plastic(hex(0x6a6e72))).beam(v(0.0, depth, r), focus, Vec3::X, 0.025, 0.025, 1.0);
    bowl.get(Mat::Plastic(hex(0x3a3d40))).beam(focus - v(0.0, 0.05, 0.0), focus + v(0.0, 0.06, 0.0), Vec3::X, 0.05, 0.05, 1.0);
    // Bowl axis is +Y: tip it to face +Z and 30 degrees up, then yaw a bit.
    let yaw = [0.35f32, -0.25, 0.1][variant as usize % 3];
    let m = Mat4::from_translation(v(0.0, 0.0, 0.35)) * Mat4::from_rotation_y(yaw) * Mat4::from_rotation_x(60f32.to_radians());
    p.append(&bowl, &m);
    let g = p.get(Mat::Galvanized);
    g.beam(v(0.0, 0.0, 0.0), v(0.0, 0.0, 0.33), Vec3::Y, 0.035, 0.035, 1.0);
    g.beam(v(-0.06, -0.08, 0.0), v(0.06, 0.08, 0.0), Vec3::Z, 0.1, 0.012, 1.0);
    p
}

/// Laundry draped over a balcony's top rail (towels, a rug, a sheet).
/// `depth` is the balcony depth so the cloth hangs on its front rail.
pub fn laundry(variant: u8, depth_cm: u16) -> P {
    let mut p = P::new();
    let zf = depth_cm as f32 / 100.0 - 0.03;
    let mut rng = Rng::new(variant as u64 * 977 + 13);
    let colors = [hex(0xf2f0ea), hex(0x3b6ea8), hex(0xd8c25a), hex(0xc0392b), hex(0x7fb3d5), hex(0xe8a0b4), hex(0x5c8a4a), hex(0x2c2c2c)];
    let pieces = 1 + variant as usize % 3;
    let mut x = -0.55 + rng.range(0.0, 0.2);
    for _ in 0..pieces {
        let w = rng.range(0.35, 0.75).min(0.75 - x);
        if w < 0.2 {
            break;
        }
        let drop = rng.range(0.35, 0.8);
        let m = if rng.chance(0.3) { Mat::Awning(rng.below(2) as u8) } else { Mat::Flowers(*rng.pick(&colors)) };
        let prim = p.get(m);
        let (x0, x1) = (x, x + w);
        // Outside face hanging from the rail, the fold on top and the
        // short inside flap.
        let top = 1.02;
        prim.quad(v(x0, top - drop, zf + 0.035), v(x1, top - drop, zf + 0.035), v(x1, top, zf + 0.035), v(x0, top, zf + 0.035), 1.0);
        prim.quad(v(x1, top - drop, zf + 0.025), v(x0, top - drop, zf + 0.025), v(x0, top, zf + 0.025), v(x1, top, zf + 0.025), 1.0);
        prim.quad(v(x0, top + 0.01, zf + 0.035), v(x1, top + 0.01, zf + 0.035), v(x1, top + 0.01, zf - 0.035), v(x0, top + 0.01, zf - 0.035), 1.0);
        prim.quad(v(x1, top - 0.25, zf - 0.035), v(x0, top - 0.25, zf - 0.035), v(x0, top, zf - 0.035), v(x1, top, zf - 0.035), 1.0);
        prim.quad(v(x0, top - 0.25, zf - 0.03), v(x1, top - 0.25, zf - 0.03), v(x1, top, zf - 0.03), v(x0, top, zf - 0.03), 1.0);
        // Pegs.
        for px in [x0 + 0.05, x1 - 0.05] {
            p.get(Mat::Plastic(*rng.pick(&[hex(0x3b8fd8), hex(0xe84a5f), hex(0xf5d33a)]))).aabox(v(px - 0.012, top - 0.03, zf + 0.03), v(px + 0.012, top + 0.04, zf + 0.05), 1.0);
        }
        x = x1 + rng.range(0.08, 0.3);
    }
    p
}

/// Clothes-line rack under a window (tendedero): two steel arms, four
/// lines and a few garments. Origin at the sill centre on the wall.
pub fn clothes_rack(variant: u8) -> P {
    let mut p = P::new();
    let mut rng = Rng::new(variant as u64 * 1543 + 7);
    let (hw, reach) = (0.65, 0.55);
    {
        let g = p.get(Mat::Galvanized);
        for x in [-hw, hw] {
            g.beam(v(x, 0.0, 0.0), v(x, 0.0, reach), Vec3::Y, 0.025, 0.025, 1.0);
            g.beam(v(x, -0.3, 0.0), v(x, 0.0, reach * 0.7), Vec3::Y, 0.02, 0.02, 1.0);
        }
    }
    let lines: Vec<f32> = (0..4).map(|i| 0.12 + i as f32 * 0.13).collect();
    {
        let l = p.get(Mat::Plastic(hex(0xdedad0)));
        for z in &lines {
            l.beam(v(-hw, 0.0, *z), v(hw, 0.0, *z), Vec3::Y, 0.006, 0.006, 1.0);
        }
    }
    let colors = [hex(0xf2f0ea), hex(0x24344d), hex(0xb03a2e), hex(0x7fb3d5), hex(0xe8d8b0), hex(0x404040), hex(0xd98cb3), hex(0x6a8f4e)];
    for z in &lines {
        let mut x = -hw + rng.range(0.03, 0.2);
        while x < hw - 0.2 {
            if rng.chance(0.65) {
                let w = rng.range(0.18, 0.45).min(hw - x);
                let drop = rng.range(0.25, 0.7);
                let m = Mat::Flowers(*rng.pick(&colors));
                let c = p.get(m);
                c.quad(v(x, -drop, *z), v(x + w, -drop, *z), v(x + w, 0.0, *z), v(x, 0.0, *z), 1.0);
                c.quad(v(x + w, -drop, *z - 0.008), v(x, -drop, *z - 0.008), v(x, 0.0, *z - 0.008), v(x + w, 0.0, *z - 0.008), 1.0);
                x += w + rng.range(0.03, 0.12);
            } else {
                x += rng.range(0.1, 0.3);
            }
        }
    }
    p
}

/// Facade lantern on a wrought-iron bracket (farol de brazo), hanging.
pub fn wall_lantern() -> P {
    wall_lantern_arm(0.7)
}

/// Wall lantern whose bracket reaches `arm` metres out of the wall (0.7
/// on wide streets, shorter in alleys).
pub fn wall_lantern_arm(arm: f32) -> P {
    let mut p = P::new();
    let iron = Mat::Iron;
    let k = arm / 0.7;
    bx(&mut p, iron, v(-0.06, -0.42, 0.0), v(0.06, 0.12, 0.03));
    {
        let a = p.get(iron);
        a.beam(v(0.0, 0.0, 0.02), v(0.0, 0.0, 0.7 * k), Vec3::X, 0.035, 0.035, 1.0);
        a.beam(v(0.0, -0.38, 0.02), v(0.0, -0.02, 0.55 * k), Vec3::X, 0.025, 0.025, 1.0);
        // Scroll: a ring between the arm and the brace.
        let r = 0.08 * k.min(1.0);
        let c = v(0.0, -0.11, 0.2 * k);
        let mut prev = c + v(0.0, r, 0.0);
        for i in 1..=10 {
            let t = std::f32::consts::TAU * i as f32 / 10.0;
            let q = c + v(0.0, t.cos() * r, t.sin() * r);
            a.beam(prev, q, Vec3::X, 0.015, 0.015, 1.0);
            prev = q;
        }
        a.beam(v(0.0, 0.0, 0.68 * k), v(0.0, -0.12, 0.68 * k), Vec3::X, 0.015, 0.015, 1.0);
    }
    lantern(&mut p, v(0.0, -0.72, 0.68 * k), 0.9, true);
    p
}

/// Pots on the ground beside a street door: a geranium, a pair, or a
/// potted shrub, `variant` 0..4.
pub fn door_pot(variant: u8) -> P {
    let mut p = P::new();
    let mut rng = Rng::new(variant as u64 * 977 + 13);
    match variant % 4 {
        0 => flower_pot(&mut p, v(0.0, 0.0, 0.2), 1.3, &mut rng),
        1 => {
            flower_pot(&mut p, v(-0.1, 0.0, 0.2), 1.3, &mut rng);
            flower_pot(&mut p, v(0.17, 0.0, 0.14), 0.9, &mut rng);
        }
        2 => {
            // A tall glazed pot with an aspidistra-like clump.
            let pot = [(0.0, 0.0), (0.1, 0.0), (0.14, 0.32), (0.155, 0.34), (0.15, 0.36), (0.12, 0.36)];
            p.get(Mat::Terracotta).lathe(v(0.0, 0.0, 0.2), &pot, 12);
            let blob: Vec<(f32, f32)> = (0..=6).map(|i| {
                let a = -std::f32::consts::FRAC_PI_2 + std::f32::consts::PI * i as f32 / 6.0;
                (a.cos() * 0.2 * if i == 0 || i == 6 { 0.0 } else { 1.0 }, 0.5 + a.sin() * 0.25)
            })
            .collect();
            p.get(Mat::Leaves).lathe(v(0.0, 0.0, 0.2), &blob, 8);
        }
        _ => {
            // A trough of geraniums along the wall.
            bx(&mut p, Mat::Terracotta, v(-0.3, 0.0, 0.04), v(0.3, 0.2, 0.26));
            for x in [-0.18, 0.0, 0.18] {
                flower_pot(&mut p, v(x, 0.06, 0.15), 0.8, &mut rng);
            }
        }
    }
    p
}

/// Tapered four-sided lantern ("fernandino"), base at `at`.
pub fn lantern(p: &mut P, at: Vec3, s: f32, hanging: bool) {
    let (b, t, h) = (0.09 * s, 0.16 * s, 0.5 * s);
    let corners = |r: f32, y: f32| [at + v(-r, y, -r), at + v(r, y, -r), at + v(r, y, r), at + v(-r, y, r)];
    let lo = corners(b, 0.0);
    let hi = corners(t, h);
    {
        let g = p.get(Mat::Glass);
        for i in 0..4 {
            let j = (i + 1) % 4;
            g.quad_uv([lo[j], lo[i], hi[i], hi[j]], [Vec2::new(0.0, 1.0), Vec2::new(1.0, 1.0), Vec2::new(1.0, 0.0), Vec2::ZERO]);
        }
    }
    {
        let iron = p.get(Mat::Iron);
        for i in 0..4 {
            iron.beam(lo[i], hi[i], Vec3::Y, 0.015 * s, 0.015 * s, 1.0);
        }
        let apex = at + v(0.0, h + 0.2 * s, 0.0);
        let cap = corners(t + 0.03 * s, h);
        for i in 0..4 {
            let j = (i + 1) % 4;
            iron.tri(cap[j], cap[i], apex, [Vec2::ZERO, Vec2::X, Vec2::Y]);
        }
        iron.lathe(apex, &[(0.0, 0.0), (0.03 * s, 0.02 * s), (0.035 * s, 0.07 * s), (0.0, 0.12 * s)], 6);
        let bottom = [(0.0, -0.08 * s), (0.04 * s, -0.06 * s), (b + 0.01 * s, 0.0)];
        iron.lathe(at, &bottom, 4);
        if hanging {
            iron.beam(apex, apex + v(0.0, 0.1 * s, 0.0), Vec3::X, 0.012, 0.012, 1.0);
        }
    }
    let bulb = p.get(Mat::Lamp(hex(0xffd9a0)));
    bulb.lathe(at + v(0.0, h * 0.25, 0.0), &[(0.0, 0.0), (0.04 * s, 0.05 * s), (0.04 * s, 0.14 * s), (0.0, 0.2 * s)], 8);
}

/// Instance transform for a module on a facade: `pos` on the wall plane,
/// `right` along the facade, `out` the wall normal.
pub fn facade_frame(pos: Vec3, right: Vec3, out: Vec3) -> Mat4 {
    Mat4::from_cols(right.extend(0.0), Vec3::Y.extend(0.0), out.extend(0.0), pos.extend(1.0))
}

/// Rotation turning +Z into `out` (horizontal).
pub fn yaw_to(out: Vec3) -> Quat {
    Quat::from_rotation_y(out.x.atan2(out.z))
}

pub fn prim_count(p: &P) -> usize {
    p.prims.values().map(Prim::tri_count).sum()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_window() -> WindowKey {
        WindowKey {
            w_cm: 115,
            h_cm: 235,
            door: true,
            surround: Mat::Moulding([240; 3]),
            surround_kind: SurroundKind::Lintel,
            frame: hex(0xf0f0f0),
            shutter: Some((ShutterKind::Alicantina, hex(0xc99a5c), 2)),
            balcony: Some(BalconyKey { width_cm: 185, depth_cm: 50, belly: true, ends: (true, true), pots: 3, awning: Some(0), terrace: 0 }),
            mirador: None,
            interior: 1,
            grille: false,
        }
    }

    #[test]
    fn window_module_is_detailed_but_bounded() {
        let p = window(&sample_window());
        let tris = prim_count(&p);
        assert!(tris > 800 && tris < 12000, "{tris} triangles");
        // Railing and glass exist.
        assert!(p.prims.contains_key(&Mat::Iron) && p.prims.contains_key(&Mat::Glass));
        // The balcony projects out of the wall, the interior sits behind it.
        let zs: Vec<f32> = p.prims.values().flat_map(|q| q.positions.iter().map(|v| v.z)).collect();
        assert!(zs.iter().cloned().fold(f32::MIN, f32::max) > 0.45);
        assert!(zs.iter().cloned().fold(f32::MAX, f32::min) < -1.5);
    }

    #[test]
    fn every_shutter_and_ground_floor_variant_builds() {
        for kind in [ShutterKind::Alicantina, ShutterKind::Louvre, ShutterKind::Roller] {
            for state in 0..4 {
                let mut k = sample_window();
                k.shutter = Some((kind, hex(0x553322), state));
                assert!(prim_count(&window(&k)) > 0);
            }
        }
        let s = shop(&ShopKey { w_cm: 300, h_cm: 330, surround: Mat::Ashlar([255; 3]), sign: 3, shutter: 3, graffiti: 1, frame: hex(0x222222), awning: Some(1), interior: 0 });
        assert!(s.prims.contains_key(&Mat::MetalShutter(1)));
        let d = portal(&PortalKey { w_cm: 200, h_cm: 360, surround: Mat::Granite, door: hex(0x4a2e1c) });
        assert!(prim_count(&d) > 100);
        for m in [balustrade(Mat::Moulding([250; 3])), pedestal(Mat::Moulding([250; 3]), true), crest(Mat::Moulding([250; 3]), Mat::Tiles(crate::texgen::TilePattern::Frieze), 3.6), dormer(Mat::Zinc, Mat::RoofSlate, hex(0xffffff)), chimney(Mat::Brick([255; 3])), wall_lantern(), terrace_railing()] {
            assert!(prim_count(&m) > 10);
        }
        // A 1970s terrace: parapet up to the handrail, no corbels.
        let mut k = sample_window();
        for terrace in 1..=4 {
            k.balcony = Some(BalconyKey { width_cm: 340, depth_cm: 110, belly: false, ends: (true, false), pots: 0, awning: Some(1), terrace });
            let b = window_piece(&k.for_piece(Piece::Balcony), Piece::Balcony);
            let pts: Vec<Vec3> = b.prims.values().flat_map(|q| q.positions.iter().copied()).collect();
            assert!(pts.iter().any(|p| p.y > 0.95 && p.z > 1.0), "terrace {terrace}: guarded to handrail height");
            assert!(pts.iter().all(|p| p.y > -0.25 || p.z < 0.0), "terrace {terrace}: no corbels under a cantilevered slab");
        }
        // Aerials stand on their foot and stay slim.
        for v in 0..3 {
            let a = tv_antenna(v);
            let ys: Vec<f32> = a.prims.values().flat_map(|q| q.positions.iter().map(|p| p.y)).collect();
            assert!(ys.iter().cloned().fold(f32::MAX, f32::min) >= -0.03);
            assert!(ys.iter().cloned().fold(f32::MIN, f32::max) > 2.5);
            assert!(prim_count(&a) < 2000);
        }
    }
}
